//! Python-vs-Rust parity sweep: replays every line of
//! `tests/parity_reference.txt` (generated by the frozen Python module:
//! `python3 /tmp/gen_parity_tl.py > rust/tests/parity_reference.txt`)
//! through the Rust port and requires 0 mismatches.
//!
//! Coverage: SplitMix64 streams (next_u64 / uniform / randint / poisson),
//! task generation, individual run_task outcomes (3 seeds x 10 tasks x
//! 3 policies x 3 mean_extra x 4 p_undo = 1080 runs), and run_experiment
//! aggregates (3 seeds x 3 policies x 3 mean_extra = 27 experiments).
//!
//! One documented tolerance: `mean_post_share` is compared within 1e-12
//! rather than exactly. Python 3.12+ `sum()` uses Neumaier compensated
//! summation for floats while Rust's `Iterator::sum` is naive, so the
//! mean of ~600 float post-shares can differ by 1 ulp. Every other
//! aggregate derives from integer sums and matches exactly.

use termination_lag::*;

const REFERENCE: &str = include_str!("parity_reference.txt");

fn parse_diff(s: &str) -> Difficulty {
    match s {
        "easy" => Difficulty::Easy,
        "medium" => Difficulty::Medium,
        "hard" => Difficulty::Hard,
        _ => panic!("bad difficulty {}", s),
    }
}

fn parse_policy(s: &str) -> Policy {
    match s {
        "continue" => Policy::Continue,
        "stop_on_pass" => Policy::StopOnPass,
        "fixed_budget" => Policy::FixedBudget,
        _ => panic!("bad policy {}", s),
    }
}

fn parse_f(s: &str) -> f64 {
    s.parse::<f64>().unwrap()
}

fn close(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-12
}

#[test]
fn parity_sweep_zero_mismatches() {
    let mut mismatches: Vec<String> = Vec::new();
    let mut n_run = 0usize;
    let mut n_exp = 0usize;

    for (lineno, line) in REFERENCE.lines().enumerate() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "rng" => {
                let seed: u64 = f[1].parse().unwrap();
                let mut r = Rng::new(seed);
                for (i, want) in f[2..].iter().enumerate() {
                    let got = r.next_u64();
                    let want: u64 = want.parse().unwrap();
                    if got != want {
                        mismatches.push(format!(
                            "line {} rng seed {} draw {}: got {} want {}",
                            lineno, seed, i, got, want
                        ));
                    }
                }
            }
            "uniform" => {
                let seed: u64 = f[1].parse().unwrap();
                let mut r = Rng::new(seed);
                for (i, want) in f[2..].iter().enumerate() {
                    let got = r.uniform();
                    let want = parse_f(want);
                    if got != want {
                        mismatches.push(format!(
                            "line {} uniform seed {} draw {}: got {:?} want {:?}",
                            lineno, seed, i, got, want
                        ));
                    }
                }
            }
            "randint03" => {
                let seed: u64 = f[1].parse().unwrap();
                let mut r = Rng::new(seed);
                for (i, want) in f[2..].iter().enumerate() {
                    let got = r.randint(0, 3);
                    let want: u64 = want.parse().unwrap();
                    if got != want {
                        mismatches.push(format!(
                            "line {} randint03 seed {} draw {}: got {} want {}",
                            lineno, seed, i, got, want
                        ));
                    }
                }
            }
            "poisson" => {
                let seed: u64 = f[1].parse().unwrap();
                let lam = parse_f(f[2]);
                let mut r = Rng::new(seed);
                for (i, want) in f[3..].iter().enumerate() {
                    let got = r.poisson(lam);
                    let want: u64 = want.parse().unwrap();
                    if got != want {
                        mismatches.push(format!(
                            "line {} poisson seed {} lam {} draw {}: got {} want {}",
                            lineno, seed, lam, i, got, want
                        ));
                    }
                }
            }
            "taskgen" => {
                let seed: u64 = f[1].parse().unwrap();
                let n: usize = f[2].parse().unwrap();
                let tasks = gen_tasks(n, seed);
                assert_eq!(tasks.len(), n);
                for (i, want) in f[3..].iter().enumerate() {
                    if tasks[i].difficulty.as_str() != *want {
                        mismatches.push(format!(
                            "line {} taskgen seed {} task {}: got {} want {}",
                            lineno,
                            seed,
                            i,
                            tasks[i].difficulty.as_str(),
                            want
                        ));
                    }
                }
            }
            "run" => {
                n_run += 1;
                let seed: u64 = f[1].parse().unwrap();
                let idx: u64 = f[2].parse().unwrap();
                let diff = parse_diff(f[3]);
                let pol = parse_policy(f[4]);
                let me = parse_f(f[5]);
                let pu = parse_f(f[6]);
                let mut rng = Rng::new(seed ^ idx.wrapping_mul(0x9E3779B97F4A7C15));
                let r = run_task(Task { idx, difficulty: diff }, pol, &mut rng, me, pu, 10, 1.0);
                let want_steps: u32 = f[7].parse().unwrap();
                let want_fcs: Option<u32> = if f[8] == "-" { None } else { Some(f[8].parse().unwrap()) };
                let want_fes: bool = f[9] == "1";
                let want_final: bool = f[10] == "1";
                let want_lag: u32 = f[11].parse().unwrap();
                let want_post: f64 = parse_f(f[12]);
                let want_undo_bad: bool = f[13] == "1";
                let want_v: u32 = f[14].parse().unwrap();
                let want_e: u32 = f[15].parse().unwrap();
                let want_r: u32 = f[16].parse().unwrap();
                let want_u: u32 = f[17].parse().unwrap();
                let want_solved: bool = f[18] == "1";
                let checks = [
                    ("steps", r.steps == want_steps),
                    ("first_correct_step", r.first_correct_step == want_fcs),
                    ("first_edit_solved", r.first_edit_solved == want_fes),
                    ("final_correct", r.final_correct == want_final),
                    ("lag", r.lag == want_lag),
                    ("post_share", r.post_share == want_post),
                    ("undo_to_incorrect", r.undo_to_incorrect == want_undo_bad),
                    ("n_verify", r.n_verify == want_v),
                    ("n_explore", r.n_explore == want_e),
                    ("n_reedit", r.n_reedit == want_r),
                    ("n_undos", r.n_undos == want_u),
                    ("solved", r.solved == want_solved),
                ];
                for (name, ok) in checks {
                    if !ok {
                        mismatches.push(format!(
                            "line {} run seed {} idx {} {} {} me {} pu {}: field {} differs (rust {:?} vs ref line)",
                            lineno, seed, idx, diff.as_str(), pol.as_str(), me, pu, name, r
                        ));
                    }
                }
            }
            "exp" => {
                n_exp += 1;
                let seed: u64 = f[1].parse().unwrap();
                let n: usize = f[2].parse().unwrap();
                let pol = parse_policy(f[3]);
                let me = parse_f(f[4]);
                let tasks = gen_tasks(n, seed);
                let m = run_experiment(pol, &tasks, seed, me, P_UNDO, 10, 1.0);
                let want_n_solved: usize = f[5].parse().unwrap();
                let want = [
                    ("success_rate", m.success_rate, parse_f(f[6])),
                    ("first_edit_solve_share", m.first_edit_solve_share, parse_f(f[7])),
                    ("mean_lag", m.mean_lag, parse_f(f[8])),
                    ("median_lag", m.median_lag, parse_f(f[9])),
                    ("median_post_share", m.median_post_share, parse_f(f[10])),
                    ("mean_post_share", m.mean_post_share, parse_f(f[11])),
                    ("final_correct_rate", m.final_correct_rate, parse_f(f[12])),
                    ("undo_to_incorrect_rate", m.undo_to_incorrect_rate, parse_f(f[13])),
                    ("mean_undos", m.mean_undos, parse_f(f[14])),
                    ("mean_total_steps", m.mean_total_steps, parse_f(f[15])),
                    ("post_verify_share", m.post_verify_share, parse_f(f[16])),
                    ("post_explore_share", m.post_explore_share, parse_f(f[17])),
                    ("post_reedit_share", m.post_reedit_share, parse_f(f[18])),
                ];
                if m.n_solved != want_n_solved {
                    mismatches.push(format!(
                        "line {} exp seed {} {} me {}: n_solved {} != {}",
                        lineno, seed, pol.as_str(), me, m.n_solved, want_n_solved
                    ));
                }
                for (name, got, w) in want {
                    // mean_post_share: 1-ulp Neumaier-vs-naive-sum tolerance.
                    let ok = if name == "mean_post_share" {
                        close(got, w)
                    } else {
                        got == w
                    };
                    if !ok {
                        mismatches.push(format!(
                            "line {} exp seed {} {} me {}: {} got {:?} want {:?}",
                            lineno, seed, pol.as_str(), me, name, got, w
                        ));
                    }
                }
            }
            other => panic!("line {}: unknown record {}", lineno, other),
        }
    }

    assert_eq!(n_run, 1080, "expected 1080 run lines, got {}", n_run);
    assert_eq!(n_exp, 27, "expected 27 exp lines, got {}", n_exp);
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{}",
        mismatches.len(),
        mismatches.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}
